 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 crop:'<path d="M12 22V2M12 9c-5 0-8-2-8-7M12 13c5 0 8-2 8-7M12 17c-5 0-8-2-8-7"/>',
 compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',
