      <label class="switch-field"><span>Mùa vụ</span><select class="v5-season-select" aria-label="Chuyển mùa vụ" ${mySeason()?'':'disabled'}>${mySeason()?seasonsOf(st.plot).map(s=>`<option value="${esc(s.id)}" ${st.season===s.id?'selected':''}>${esc(s.name)}</option>`).join(''):'<option>Chưa có mùa vụ</option>'}</select></label>
