  plotsPage=function(){return smallContext()+`<div class="content-width">${head('Farming Service','Ruộng lúa của tôi','Mỗi ruộng có thể có nhiều mùa vụ. Chọn ruộng để xem hoặc tạo mùa vụ.')}<div class="card"><div class="card-row"><h2>Danh sách ruộng (${d.plots.filter(x=>x.visible).length})</h2><button class="btn primary" data-action="new-plot">${ic('plus','sm')}Thêm ruộng</button></div></div>${d.plots.filter(p=>p.visible).map(p=>{const seasons=seasonsOf(p.id),curr=seasons.find(x=>x.status==='IN_PROGRESS')||seasons[0];return `<button class="listing-card" data-plot="${p.id}"><div class="row" style="align-items:start"><div class="mini-rice">${ic('field','xl')}</div><div class="flex1"><div class="card-row"><div class="listing-title">${esc(p.name)}</div>${curr?status(curr.status,'season'):'<span class="chip neutral">Chưa có mùa vụ</span>'}</div><div class="listing-sub">${ic('pin','sm')}${esc(p.location)}</div><div class="listing-meta"><span>${ic('field','sm')}${num(p.area)} m²</span><span>${ic('calendar','sm')}${seasons.length} mùa vụ</span><span>${ic('sprout','sm')}${esc(curr?.crop||'Chưa khai báo giống lúa')}</span></div></div>${ic('chevron')}</div></button>`}).join('')}<div class="callout info">Mỗi mùa vụ thuộc một ruộng cụ thể. Các dữ liệu chi phí/nhật ký được xem theo mùa vụ đang chọn.</div></div>`;};

